"""Verify and export the exact scientific source trees in a publication archive."""

from __future__ import annotations

import hashlib
import json
import os
from pathlib import Path
import shutil

# These may be generated by Python/test runs in an otherwise unchanged archive.
CACHES = {"__pycache__", ".pytest_cache", ".ruff_cache"}


def source_tree(path):
    """Return the Git tree identity, including executable bits, without Git metadata.

    SHA-1 here reproduces Git's content addressing of the original pinned tree;
    it is not used as a credential or an authentication mechanism.
    """
    rows = []
    with os.scandir(path) as entries:
        for entry in entries:
            if entry.name in CACHES or entry.name.endswith((".pyc", ".pyo")):
                continue
            if entry.is_symlink():
                raise ValueError(f"Bundled source contains a symlink: {entry.name}")
            name = os.fsencode(entry.name)
            if entry.is_dir(follow_symlinks=False):
                oid = source_tree(Path(entry.path))
                # Git does not represent empty directories.
                if oid == hashlib.sha1(b"tree 0\0").digest():
                    continue
                mode, key = b"40000", name + b"/"
            elif entry.is_file(follow_symlinks=False):
                size = entry.stat().st_size
                digest = hashlib.sha1(f"blob {size}\0".encode())
                with open(entry.path, "rb") as stream:
                    while block := stream.read(1024 * 1024):
                        digest.update(block)
                oid = digest.digest()
                mode = b"100755" if entry.stat().st_mode & 0o111 else b"100644"
                key = name
            else:
                raise ValueError(f"Bundled source contains a non-file: {entry.name}")
            rows.append((key, mode + b" " + name + b"\0" + oid))
    payload = b"".join(row for _, row in sorted(rows))
    return hashlib.sha1(f"tree {len(payload)}\0".encode() + payload).digest()


def verify_bundled(root, entry):
    """Return False in a development checkout; fail closed for invalid bundles."""
    manifest = root / "tools/bundled-sources.json"
    if not manifest.exists():
        return False
    if manifest.is_symlink():
        raise ValueError("Bundled source manifest must not be a symlink")
    document = json.loads(manifest.read_text())
    if document.get("schema_version") != 1:
        raise ValueError("Unsupported bundled source manifest")
    records = document.get("tools", [])
    matches = [record for record in records if record.get("name") == entry["name"]]
    if len(matches) != 1:
        raise ValueError(f"{entry['name']}: missing or duplicate bundled source identity")
    record = matches[0]
    if any(record.get(key) != entry[key] for key in ("repository", "commit", "path")):
        raise ValueError(f"{entry['name']}: bundled source differs from requested lock")
    path = root / entry["path"]
    if path.is_symlink() or not path.is_dir():
        raise ValueError(f"{entry['name']}: missing or unsafe bundled source directory")
    if source_tree(path).hex() != record.get("tree"):
        raise ValueError(f"{entry['name']}: bundled source tree has changed")
    return True


def export_bundled(root, entry, destination):
    if not verify_bundled(root, entry):
        return False
    shutil.copytree(
        root / entry["path"], destination,
        ignore=shutil.ignore_patterns(*CACHES, "*.pyc", "*.pyo"),
    )
    return True
